require 'async'
require 'async/barrier'

xlsx_files = Dir.glob("tmp/lalen/*.xlsx")
codes = []
# pp xlsx_files

barrier = Async::Barrier.new

Async do
	xlsx_files.each do |xlsx_path|
		barrier.async do
			puts xlsx_path
			xlsx = Roo::Excelx.new(xlsx_path)
			column_index = 2

			(2..xlsx.last_row).each do |row_index|
				value = xlsx.cell(row_index, column_index)  # Get value from specified column
				codes << value
			end

			rescue StandardError => ex
				puts ex.full_message
		end
	end

	barrier.wait
end

pp codes.map { |c| c.to_s }.join(" ")
puts codes.size

